// One start time for the prompt and for the heading of the LLM Recommendations Log, so that the
// round's records in both logs get the same date and time.
const iso = new Date().toISOString();

return [{
  json: {
    date: iso.slice(0, 10),
    time: iso.slice(11, 16),
  },
}];

// The prompt API answers 502 with { status: 'error', message } when Claude Code fails,
// 409 when another prompt runs, and the request fails when the pod is down.
// cluster-helper answers 502 with { status: 'error', message } naming the target that failed
// (Telegram, the LLM Recommendations Log or both); the other one was still delivered.
// No retry: the message may already be in Telegram.
const item = $input.first().json;
const err = item.error ?? item;
const message = (err && err.message) ? err.message : JSON.stringify(err).slice(0, 300);

return [{
  json: {
    text: `⚠️ Failed to run the job search round: ${message}`,
  },
}];
